package com.nthexperience.desktop;

import android.content.Context;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import org.json.*;

final class GadgetGallery extends VistaShell {
    interface Host extends Actions {void changed();void reveal();}
    private final WeatherClient weather;private final Host host;private String category="All gadgets",selected="clock";private int columns=2;
    private static final String[] CATEGORIES={"All gadgets","Time","Information","Productivity","Device","Photos","Games"};
    GadgetGallery(Context c,DesktopStore store,WeatherClient weather,Host host){super(c,store,host,"Search Gadget Gallery");this.weather=weather;this.host=host;TextView show=command("Show gadgets",host::reveal);show.setContentDescription("Show desktop gadgets");commands.addView(show,new LayoutParams(-2,dp(36)));commands.addView(command("Category ▾",this::categories),new LayoutParams(-2,dp(36)));start("home");addOnLayoutChangeListener((v,l,t,right,b,ol,ot,or,ob)->{int next=right-l>=dp(720)?3:2;if(next!=columns){columns=next;post(this::render);}});}
    @Override void render(){
        side.removeAllViews();for(String name:CATEGORIES)sideLink(name,()->{category=name;render();});sideLink("Personalization",()->host.open("@appearance"));address.setText("Desktop Gadget Gallery  ›  "+category);LinearLayout column=column();heading(column,"Desktop Gadget Gallery","Select a gadget, then add it to your desktop.");TextView hint=Aero.text(getContext(),"Hold a gadget to drag it. Use its gear for options or the corner grip to resize it.",12,0xff586976);hint.setTypeface(android.graphics.Typeface.create(Aero.face(getContext()),android.graphics.Typeface.ITALIC));column.addView(hint);GridLayout grid=new GridLayout(getContext());grid.setColumnCount(columns);grid.setBackground(Aero.panel(getContext(),0xfff5f9fc,0xffe3eef6,3,0xffa5bbcb));column.addView(grid,new LayoutParams(-1,-2));int count=0;
        for(String[] item:GadgetCatalog.ITEMS){String id=item[0];if(!category.equals("All gadgets")&&!category.equals(item[2]))continue;if(!query().isEmpty()&&!(item[1]+" "+item[2]+" "+item[3]).toLowerCase(java.util.Locale.ROOT).contains(query()))continue;count++;LinearLayout cell=Aero.column(getContext());cell.setGravity(Gravity.CENTER);cell.setPadding(dp(7),dp(8),dp(7),dp(8));cell.setBackground(id.equals(selected)?Aero.panel(getContext(),0xffe2f4ff,0xffc1e1f5,3,0xff79a9c8):Aero.selection(getContext()));FrameLayout preview=new FrameLayout(getContext());preview.setBackground(Aero.panel(getContext(),0xffe2edf3,0xffbacfdd,4,0xffa4b9c7));GadgetView face=new GadgetView(getContext(),id,store,weather);preview.addView(face,new FrameLayout.LayoutParams(dp(102),dp(110),Gravity.CENTER));preview.setContentDescription("Select "+item[1]+" gadget");preview.setFocusable(true);preview.setOnClickListener(v->{selected=id;render();});cell.addView(preview,new LayoutParams(-1,dp(115)));TextView title=Aero.text(getContext(),item[1],13,Aero.INK);title.setGravity(Gravity.CENTER);cell.addView(title,new LayoutParams(-1,dp(30)));TextView toggle=Aero.button(getContext(),store.gadgets().contains(id)?"Remove":"Add",()->{});toggle.setContentDescription((store.gadgets().contains(id)?"Remove ":"Add ")+item[1]+" gadget");toggle.setOnClickListener(v->{java.util.List<String> enabled=store.gadgets();if(enabled.contains(id))enabled.remove(id);else enabled.add(id);store.gadgets(enabled);host.changed();if(enabled.contains(id))host.reveal();toggle.setText(enabled.contains(id)?"Remove":"Add");toggle.setContentDescription((enabled.contains(id)?"Remove ":"Add ")+item[1]+" gadget");status.setText(GadgetCatalog.IDS.length+" available gadgets  •  "+enabled.size()+" on your desktop");});cell.addView(toggle,new LayoutParams(-1,dp(40)));TextView settings=link(cell,"Settings",()->open(id));settings.setGravity(Gravity.CENTER);settings.setContentDescription("Settings for "+item[1]+" gadget");TextView details=link(cell,"Show details",()->Aero.dialog(getContext()).setTitle(item[1]).setMessage(item[3]+"\n\nCategory: "+item[2]+"\nNative Nth gadget • Version "+AppInfo.version(getContext())+"\n\nPlace it anywhere on the desktop. Its position and settings are saved.").setPositiveButton("OK",null).show());details.setGravity(Gravity.CENTER);details.setContentDescription("Details for "+item[1]+" gadget");GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.width=0;p.bottomMargin=dp(8);grid.addView(cell,p);}
        for(String[] item:GadgetCatalog.ITEMS)if(item[0].equals(selected)){TextView information=Aero.text(getContext(),item[1]+"  •  Nth Desktop "+AppInfo.version(getContext())+"\n"+item[3],12,Aero.INK);information.setContentDescription("Selected gadget details");Aero.pad(information,10);information.setBackground(Aero.panel(getContext(),0xffe9f2f8,0xffd2e6f4,2,0xffa4bdcf));column.addView(information);}if(count==0)heading(column,"No matching gadgets","Try another category or clear your search.");CheckBox lock=Aero.check(getContext(),"Lock desktop layout",store.prefs.getBoolean("layout_locked",false));lock.setContentDescription("Lock desktop layout");lock.setOnCheckedChangeListener((v,value)->store.prefs.edit().putBoolean("layout_locked",value).apply());column.addView(lock);CheckBox snap=Aero.check(getContext(),"Snap gadgets to grid",store.prefs.getBoolean("snap_gadgets",true));snap.setOnCheckedChangeListener((v,value)->store.prefs.edit().putBoolean("snap_gadgets",value).apply());column.addView(snap);status.setText(count+" available gadgets  •  "+store.gadgets().size()+" on your desktop");body(scrolling(column));
    }
    private void open(String kind){host.action("gadget:"+kind);}
    private void categories(){DesktopContextMenu menu=new DesktopContextMenu(getContext(),"Gadget categories");for(String name:CATEGORIES)menu.checked(name,name.equals(category),()->{category=name;render();});ContextMenus.centered(commands,(x,y)->ContextMenus.show(menu,commands,x,y));}
    @Override void showFolders(){categories();}
    @Override void goUp(){category="All gadgets";render();}
    @Override JSONObject extraState(){JSONObject state=new JSONObject();GadgetLayout.put(state,"category",category);GadgetLayout.put(state,"selected",selected);return state;}
    @Override void restoreExtra(JSONObject state){if(state!=null){if(java.util.Arrays.asList(CATEGORIES).contains(state.optString("category")))category=state.optString("category");if(java.util.Arrays.asList(GadgetCatalog.IDS).contains(state.optString("selected")))selected=state.optString("selected");}}
    @Override void refreshApps(){render();}
}
